router.get('/api/trading/accounts/:accountId/trades-stream', requireAuth, async (req, res) => {
  const account = await TradingAccount.findOne({
    where: { id: req.params.accountId, ownerId: req.user.id }
  });
  if (!account) {
    return res.status(403).json({ error: 'Access denied: target trading account not owned by user' });
  }

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const sub = redisClient.duplicate();
  await sub.connect();
  await sub.subscribe(`trades:${req.params.accountId}`, (message) => {
    res.write(`data: ${message}\n\n`);
  });

  req.on('close', async () => {
    await sub.unsubscribe(`trades:${req.params.accountId}`);
    await sub.quit();
  });
});
